  model_number = v.model_number, official_item_name = v.official_item_name, status = v.status,
  raw_value = v.raw_value, raw_unit = v.raw_unit, official_kg_text = v.official_kg_text,
  weight_kg = v.weight_kg, basis = v.basis, source_url = v.source_url,
  checked_date = v.checked_date, notes = v.notes
